a=[]
def p(t=''):a.append(t.rstrip()+'\n')
def table(head,rows):
 # Emit one block: GFM tables cannot contain blank lines between rows.
 lines=['| '+' | '.join(head)+' |','| '+' | '.join('---'for _ in head)+' |']
 for row in rows:lines.append('| '+' | '.join(str(x).replace('|','/')for x in row)+' |')
 p('\n'.join(lines))
def n(x):return f'{x:.4g}'if isinstance(x,float)else str(x)
